def kthSmallest(matrix: list[list[int]], k: int) -> int:
    n = len(matrix)
    lo, hi = matrix[0][0], matrix[n - 1][n - 1]
    def count_less_equal(mid):
        count = 0
        c = n - 1
        for r in range(n):
            while c >= 0 and matrix[r][c] > mid: c -= 1
            count += (c + 1)
        return count
    while lo < hi:
        mid = (lo + hi) // 2
        if count_less_equal(mid) < k:
            lo = mid + 1
        else:
            hi = mid
    return lo

